#!/bin/bash
# shellcheck disable=SC2015
set -eEuo pipefail
# usvNamen (commit63): lokale USV heisst USV SPITZBODEN, USV EG ist nicht verbunden.
# Kein Polling und keine Steuerung des EG-Geraets. SoH nur aus gelernter Laufzeit.
# Abschaltung 20 % oder 5 min und der Netzausfall-Alarm bleiben unveraendert.
# lage_pages.py: zwei bekannte Basen (ungekuerzt oder die 3-Zeilen-Kuerzung). Alles andere STOP.
# Aufruf: bash apply-commit63.sh commit63 [dry-run]
# Simulation: DASH_PORT=5093 C61_SIM_DIR C61_SIM_W C61_FAKE_HM C61_RETRY_S C61_WAIT_S C61_SIM_NOMUT C61_READY_S
COMMIT_ARG="${1:-unbekannt}"
MODE_ARG="${2:-}"
case "$MODE_ARG" in ""|dry-run|--dry-run|dryrun|trockenlauf) ;; *) echo "STOP: unbekannter zweiter Parameter '$MODE_ARG' (erlaubt: dry-run) - nichts geaendert"; exit 1;; esac
DRY=0; [[ -n "$MODE_ARG" ]] && DRY=1
DASH_DIR="/home/fmg/prepper-dashboard"
W=/tmp/commit63-apply
NM=commit63
MK=usvNamen
SIM=0; [[ -n "${DASH_PORT:-}" && "${DASH_PORT:-}" != 5000 ]] && SIM=1
if [[ "$SIM" == 1 ]]; then DASH_DIR="${C61_SIM_DIR:-$DASH_DIR}"; W="${C61_SIM_W:-$W}"; fi
VPY="$DASH_DIR/venv/bin/python"
SPY=/usr/bin/python3
TS=$(date +%Y%m%d-%H%M%S)
KEEP_LAST=3
SINGLE=(dashboard.py ups_manager.py prepper_docs.py)
declare -A ALT=(
  [dashboard.py]=4898b5b62648b7d79d78e8aabb3a9e48bf3fcaf6945b7f907c3a36abb501031f
  [ups_manager.py]=ef0b9e3d4bf42003dfa5b0102e4665d0aa7bb2b5bb11d33c0d1aefc39a66034e
  [prepper_docs.py]=9675347501e9985a04c1e7d71a53a2e34e2372daa18b749a17135652fd1b5abe
)
declare -A NEU=(
  [dashboard.py]=8a055ad3ed0619f681e2575c5ad588c3a28330eba1c00daab46d1cde46e28908
  [ups_manager.py]=b2e491e36a9a1861de4c609f80a613f9b824e4f6f52319c50e5c5a87252ddcf8
  [prepper_docs.py]=8f9983737e5217a4dbaecbc8764d6889cff10f0a82a41fe7b97e1bf9671e3751
)
LAGE_ALT_FULL=536780ba4b89a69a34183d20a802251ec5f8dbc4f19b7a6a8d95c516e2e13a9f
LAGE_ALT_TRIM=5185cfefaf5dbc1c30ae6349278f1fe43832c4fed92fe7619484ae2ac7ec7e74
LAGE_NEU_FULL=d268d324f4fd55a53cb7ee1919e3fb399e2c4ca0a7733780c9bf977b0fee2fca
LAGE_NEU_TRIM=6b10e3bae7118d9519760b492220e88a5caf2e9dc99e9ed8db096eb911d0e778
declare -A KEEP=(
  [gas_saison.py]=1a258f195e59528b23841e350fdf505959d461f7779c7969ef0264980ee875d4
  [prepper_sdr.py]=b879ab56f4ac4736
  [sdr_manager.py]=5a26efff608bf541
  [database.py]=2754d0bdddca9400
  [prepper_evlog.py]=8bffd396972b60fa
)
DOCS="$DASH_DIR/docs"
PHASE=vorher
FINISHED=0
RESTARTED=0
GEN_RAN=0
STOPPED=0
RB_DONE=0
INST=()
VARIANT=""
ERRLN=""; ERRCMD=""
trap 'ERRLN=$LINENO; ERRCMD=$BASH_COMMAND' ERR
stop() { STOPPED=1; echo "STOP: $1 - nichts geaendert"; exit 1; }
CFG_PORT=$(sed -n 's/^PORT[[:space:]]*=[[:space:]]*\([0-9][0-9]*\).*/\1/p' "$DASH_DIR/config.py" 2>/dev/null | head -1 || true)
PORT="${DASH_PORT:-${CFG_PORT:-5000}}"
if ! [[ "$PORT" =~ ^[0-9]+$ ]]; then stop "Dashboard-Port unklar ($PORT)"; fi
if [[ "$PORT" == "8080" ]]; then stop "Port 8080 ist kiwix-serve, nicht das Dashboard"; fi
if [[ "$SIM" == 1 && "$PORT" != "5093" ]]; then stop "Simulation nur auf Port 5093 (jetzt $PORT)"; fi
if [[ "$SIM" == 0 && "$PORT" != "5000" ]]; then stop "Echter Lauf nur auf Port 5000 (jetzt $PORT)"; fi
B="http://127.0.0.1:${PORT}"
CURL=(curl --compressed -s --connect-timeout 3 --max-time 40)
[[ -x "$VPY" ]] || VPY=python3
[[ -x "$SPY" ]] || SPY=python3
for t in python3 sha256sum curl flock cp mv cmp stat date timeout nice base64; do command -v "$t" >/dev/null 2>&1 || stop "Werkzeug $t fehlt"; done
s16() { sha256sum "$1" | cut -c1-16; }
sfull() { sha256sum "$1" | cut -d' ' -f1; }
on_exit() {
  local ec=$?
  if [[ $ec -ne 0 && $FINISHED -eq 0 ]]; then
    if [[ "$PHASE" == vorher ]]; then
      [[ -n "$ERRLN" && "$STOPPED" == 0 ]] && echo "ABBRUCH: unerwarteter Fehler (Exit $ec) in Zeile $ERRLN, Befehl: $(echo "$ERRCMD" | cut -c1-400) - es wurde noch nichts geaendert"
    elif [[ "$PHASE" == installiert && "$RB_DONE" == 0 ]]; then
      echo "ABBRUCH: unerwarteter Fehler (Exit $ec) in Zeile ${ERRLN:-?}, Befehl: $(echo "${ERRCMD:-?}" | cut -c1-400) - Rollback"
      rb "unerwarteter Fehler" || true
    fi
  fi
}
trap on_exit EXIT
echo "=== $MK apply ($COMMIT_ARG$([[ "$DRY" == 1 ]] && echo ", TROCKENLAUF")): USV SPITZBODEN / USV EG, Port $PORT, Ordner $DASH_DIR ==="
umask 022
mkdir -p "$(dirname "$W")"
exec 9>"$W.lock"
flock -n 9 || stop "ein anderer $NM-Lauf ist aktiv (Sperre $W.lock)"
rm -rf "$W" && mkdir -p "$W/neu" "$W/alt" "$W/html" && chmod 700 "$W"
python3 - "$W/neu" << 'MK_PAY_EOF'
import base64, hashlib, os, sys
dest = sys.argv[1]
os.makedirs(dest, exist_ok=True)
raw = {
    'dashboard.py': '',
    'ups_manager.py': '',
    'prepper_docs.py': '',
    'lage_full.py': '',
    'lage_trim.py': '',
}
expect = {
    'dashboard.py': '8a055ad3ed0619f681e2575c5ad588c3a28330eba1c00daab46d1cde46e28908',
    'ups_manager.py': 'b2e491e36a9a1861de4c609f80a613f9b824e4f6f52319c50e5c5a87252ddcf8',
    'prepper_docs.py': '8f9983737e5217a4dbaecbc8764d6889cff10f0a82a41fe7b97e1bf9671e3751',
    'lage_full.py': 'd268d324f4fd55a53cb7ee1919e3fb399e2c4ca0a7733780c9bf977b0fee2fca',
    'lage_trim.py': '6b10e3bae7118d9519760b492220e88a5caf2e9dc99e9ed8db096eb911d0e778',
}
for name, b64 in raw.items():
    data = base64.b64decode(b64)
    got = hashlib.sha256(data).hexdigest()
    if got != expect[name]:
        sys.stderr.write("FEHLER sha256 %s %s\n" % (name, got))
        sys.exit(1)
    tmp = os.path.join(dest, name + ".tmp")
    with open(tmp, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, os.path.join(dest, name))
print("OK Nutzlast sha256 geprueft (%d Dateien)" % len(raw))
MK_PAY_EOF
EXPECT_GRD='52634ccb52afe34846997d35eff61ee7ae492ec554198a6cea145d1cd0c1d0ab'
cat > "$W/guard.py" << 'MK_GRD_EOF'
#!/usr/bin/env python3
"""guard63.py check ALT NEU VAR | mutate ALT NEU
VAR ist full oder trim. Prueft nur die USV-Anzeige. Abschaltung und Netzausfall-Alarm bleiben."""
import re
import sys

SHUT = "Abschaltung bei 20 % oder 5 min · upsmon aktiv"
LOW = "USVA_LOW_S = 300"
OB = "OB_CONFIRM_S = 20"


def read(path):
    with open(path, encoding="utf-8") as f:
        return f.read()


def routes(src):
    return src.count("@app.route("), src.count("add_url_rule(")


def chk(alt_dash, neu, variant):
    err = []
    um, d, p, docs = neu["ups_manager.py"], neu["dashboard.py"], neu["lage_pages.py"], neu["prepper_docs.py"]
    if 'HOST = "127.0.0.1"' not in um:
        err.append("NUT-Host ist nicht mehr nur lokal")
    if "192.168.178.3" in um.split("def unit_eg", 1)[0]:
        err.append("EG-Adresse steht vor dem Platzhalter")
    if re.search(r"create_connection\(\([^)]*192\.168\.178\.3", um):
        err.append("EG-Geraet wird abgefragt")
    if '"polling": True' in um.split("def unit_eg", 1)[-1].split("def decorate", 1)[0]:
        err.append("Platzhalter pollt")
    soh_fn = um.split("def soh", 1)[-1].split("def runtime_smoothed", 1)[0]
    if "100.0 * _med(rc) / base[k]" not in soh_fn:
        err.append("SoH nicht mehr aus der Laufzeit")
    if re.search(r'"wechsel": "[0-9]{4}', um):
        err.append("Austauschdatum erfunden")
    if OB not in um or LOW not in d or d.count(SHUT) != 3:
        err.append("Abschaltung oder Netzausfall-Schwelle geaendert")
    if routes(d) != routes(alt_dash):
        err.append("Routen geaendert")
    if "USV SPITZBODEN" not in p or 'id="usvEg"' not in p or "nicht verbunden" not in p:
        err.append("USV-Kacheln fehlen")
    if "nicht festgelegt" not in p or "192.168.178.3" not in p:
        err.append("Platzhalter ohne Host oder ohne offenes Wechseldatum")
    if "20 % Ladung oder 5 min" not in p:
        err.append("Hinweis auf die bestehende Abschaltung fehlt")
    note = 'get("scenario_note")' in p
    prof = 'get("profile_text")' in p
    if variant == "trim" and (note or prof):
        err.append("Speicher-Kuerzung wurde rueckgaengig gemacht")
    if variant == "full" and not (note and prof):
        err.append("ungekuerzte Speicher-Seite verliert Profil oder Szenariohinweis")
    if "usvNamen" not in docs or "USV EG" not in docs:
        err.append("Projektbeschreibung ohne USV-Namen")
    if "20 % oder 5 min" not in docs:
        err.append("Doku zur Abschaltung geaendert")
    return err


def main():
    if len(sys.argv) < 4:
        print("Aufruf: guard63.py check|mutate ALT NEU [full|trim]")
        sys.exit(2)
    cmd, alt, neu = sys.argv[1], sys.argv[2], sys.argv[3]
    variant = sys.argv[4] if len(sys.argv) > 4 else "full"
    files = {}
    for name in ("ups_manager.py", "dashboard.py", "lage_pages.py", "prepper_docs.py"):
        files[name] = read("%s/%s" % (neu, name))
    alt_dash = read("%s/dashboard.py" % alt)
    if cmd == "check":
        e = chk(alt_dash, files, variant)
        if e:
            print("\n".join("VERSTOSS " + x for x in e))
            sys.exit(1)
        print("Guard usvNamen ok: lokale USV benannt, EG ohne Abruf, SoH nicht aus Ladung, Abschaltung unveraendert, Speicher-Kuerzung bleibt")
        return
    um, d, p = files["ups_manager.py"], files["dashboard.py"], files["lage_pages.py"]

    def put(**kw):
        out = dict(files)
        out.update(kw)
        return out

    mut = [
        ("EG wird abgefragt", put(**{"ups_manager.py": um.replace('HOST = "127.0.0.1"', 'HOST = "192.168.178.3"', 1)})),
        ("Platzhalter pollt", put(**{"ups_manager.py": um.replace('"polling": False', '"polling": True', 1)})),
        ("SoH aus Ladung", put(**{"ups_manager.py": um.replace("100.0 * _med(rc) / base[k]", "ch if ch is not None else 0", 1)})),
        ("Wechseldatum erfunden", put(**{"ups_manager.py": um.replace('"wechsel": None', '"wechsel": "2030-01"', 1)})),
        ("Netzausfall nach 5 s", put(**{"ups_manager.py": um.replace("OB_CONFIRM_S = 20", "OB_CONFIRM_S = 5", 1)})),
        ("5-min-Ansage geaendert", put(**{"dashboard.py": d.replace("USVA_LOW_S = 300", "USVA_LOW_S = 60", 1)})),
        ("Abschaltungstext geaendert", put(**{"dashboard.py": d.replace(SHUT, "Abschaltung aus", 1)})),
        ("neue Route", put(**{"dashboard.py": d.replace("@app.route(\"/speicher\")", "@app.route(\"/x\")\n@app.route(\"/speicher\")", 1)})),
        ("USV EG entfernt", put(**{"lage_pages.py": p.replace('id="usvEg"', 'id="weg"', 1)})),
        ("Kuerzung zurueck", put(**{"lage_pages.py": p.replace("USV EG", 'USV EG\n{{ (gas.value or {}).get("scenario_note") }}', 1)})),
    ]
    bad = 0
    for name, changed in mut:
        # Die letzte Mutation prueft die getrimmte Sicht: scenario_note darf dort nicht auftauchen.
        var = "trim" if name == "Kuerzung zurueck" else "full"
        e = chk(alt_dash, changed, var)
        print(("erkannt  " if e else "UEBERSEHEN ") + name + (": " + e[0] if e else ""))
        if not e:
            bad += 1
    print("Mutationstest usvNamen: %d/%d erkannt" % (len(mut) - bad, len(mut)))
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()
MK_GRD_EOF
echo "$EXPECT_GRD  $W/guard.py" | sha256sum -c - >/dev/null 2>&1 || stop "sha256 von guard.py falsch (Skript beschaedigt oder veraendert - bitte neu laden)"
echo "OK eingebettete Nutzlast und Guard geprueft"
for f in "${SINGLE[@]}" lage_pages.py "${!KEEP[@]}"; do [[ -f "$DASH_DIR/$f" ]] || stop "$f fehlt im Projektordner $DASH_DIR"; done
NA=0; NN=0; ODD=""
for f in "${SINGLE[@]}"; do
  h=$(sfull "$DASH_DIR/$f")
  if [[ "$h" == "${ALT[$f]}" ]]; then NA=$((NA+1))
  elif [[ "$h" == "${NEU[$f]}" ]]; then NN=$((NN+1))
  else ODD+="$f=${h:0:16} "; fi
done
[[ -z "$ODD" ]] || stop "Stand weicht ab: ${ODD}"
LH=$(sfull "$DASH_DIR/lage_pages.py")
case "$LH" in
  "$LAGE_ALT_FULL") LAGE=alt; VARIANT=full;;
  "$LAGE_ALT_TRIM") LAGE=alt; VARIANT=trim;;
  "$LAGE_NEU_FULL") LAGE=neu; VARIANT=full;;
  "$LAGE_NEU_TRIM") LAGE=neu; VARIANT=trim;;
  *) stop "lage_pages.py ${LH:0:16} ist keine der beiden bekannten Basen (ungekuerzt ${LAGE_ALT_FULL:0:16} oder gekuerzt ${LAGE_ALT_TRIM:0:16}) und kein Zielstand. Bitte den Ist-Hash melden.";;
esac
KODD=""
for f in "${!KEEP[@]}"; do
  h=$(sfull "$DASH_DIR/$f")
  if [[ "$f" == gas_saison.py ]]; then
    [[ "$h" == "${KEEP[$f]}" ]] || KODD+="$f=${h:0:16} "
  else
    [[ "${h:0:16}" == "${KEEP[$f]}" ]] || KODD+="$f=${h:0:16} "
  fi
done
[[ -z "$KODD" ]] || stop "Unveraenderte Dateien weichen ab: ${KODD}"
if [[ "$NA" == 3 && "$LAGE" == alt ]]; then STATE=alt; echo "OK Basis commit62, lage_pages.py Variante $VARIANT (${LH:0:16})"
elif [[ "$NN" == 3 && "$LAGE" == neu ]]; then STATE=neu; echo "OK $NM ist schon installiert (Variante $VARIANT), nichts wird zurueck in die andere Speicher-Fassung geschrieben"
else
  echo "STOP: Mischstand - nichts geaendert."
  for f in "${SINGLE[@]}" lage_pages.py; do echo "      $f $(sfull "$DASH_DIR/$f" | cut -c1-16)"; done
  STOPPED=1; exit 1
fi
[[ -w "$DASH_DIR" ]] || stop "Projektordner nicht beschreibbar"
"$VPY" -c "import sys; assert sys.version_info >= (3, 9)" 2>/dev/null || stop "Python der venv ($VPY) ist aelter als 3.9 oder nicht startbar"
cp "$DASH_DIR/dashboard.py" "$W/alt/dashboard.py"
cp "$W/neu/dashboard.py" "$W/neu/ups_manager.py" "$W/neu/prepper_docs.py" "$W/check/" 2>/dev/null || mkdir -p "$W/check"
mkdir -p "$W/check"
cp "$W/neu/dashboard.py" "$W/neu/ups_manager.py" "$W/neu/prepper_docs.py" "$W/check/"
if [[ "$VARIANT" == trim ]]; then cp "$W/neu/lage_trim.py" "$W/check/lage_pages.py"; else cp "$W/neu/lage_full.py" "$W/check/lage_pages.py"; fi
python3 "$W/guard.py" check "$W/alt" "$W/check" "$VARIANT" > "$W/g.log" 2>&1 || { cat "$W/g.log"; stop "Guard $MK meldet Verstoss"; }
echo "OK $(head -1 "$W/g.log")"
MUTS=1; [[ -n "${C61_SIM_NOMUT:-}" && "$SIM" == 1 ]] && { MUTS=0; echo "SIM: Mutationstest uebersprungen"; }
if [[ "$MUTS" == 1 ]]; then
  mkdir -p "$W/full"
  cp "$W/check/dashboard.py" "$W/check/ups_manager.py" "$W/check/prepper_docs.py" "$W/full/"
  cp "$W/neu/lage_full.py" "$W/full/lage_pages.py"
  python3 "$W/guard.py" mutate "$W/alt" "$W/full" > "$W/gm.log" 2>&1 || { cat "$W/gm.log"; stop "Mutationstest $MK: eine Veraenderung wurde nicht erkannt"; }
  echo "OK $(grep -E '^Mutationstest' "$W/gm.log")"
  grep -q "UEBERSEHEN" "$W/gm.log" && { cat "$W/gm.log"; stop "Mutationstest enthaelt UEBERSEHEN"; }
fi
for py in "$SPY" "$VPY"; do
  for x in "$W/check"/*.py "$W/guard.py"; do
    "$py" -W error -c 'import sys; compile(open(sys.argv[1], encoding="utf-8").read(), sys.argv[1], "exec")' "$x" 2>"$W/pyc.log" || { cat "$W/pyc.log"; stop "py_compile $(basename "$x") mit $py meldet Fehler/Warnung"; }
  done
  ( cd "$W/check" && PYTHONDONTWRITEBYTECODE=1 timeout 90 "$py" -c 'import ups_manager; print(ups_manager.selftest())' ) > "$W/st.log" 2>&1 || { cat "$W/st.log"; stop "Selbsttest ups_manager mit $py fehlgeschlagen"; }
  grep -q "^ups_manager ok" "$W/st.log" || { cat "$W/st.log"; stop "Selbsttest ups_manager ohne ok ($py)"; }
done
echo "OK py_compile und ups_manager-Selbsttest ($SPY und $VPY)"
code() { local c; c=$("${CURL[@]}" "$@" -o /dev/null -w "%{http_code}" || true); [[ -z "$c" ]] && c=000; echo "$c"; }
code_r() { local c i; for i in 1 2 3 4 5; do c=$(code "$@"); [[ "$c" == 200 ]] && break; sleep "${C61_RETRY_S:-6}"; done; echo "$c"; }
PAGES=(/ /speicher /funk /pi /umwelt /funk433 /aprs /meteor /rundfunk /energie /dabhist /mesh /karte /lokale-energie)
APIS=(/api/sdr/ui /api/sdr/wd /api/br24 /api/sdr/sticktest /api/sdr/live /api/sdr/map /api/broadcast/events /api/t2/status /api/t3/status /api/t4/status /api/t4/map /api/t4/tii /api/meteor /api/sdr/status /api/usv /api/docs/list)
declare -A PRE
for p in "${PAGES[@]}" "${APIS[@]}"; do PRE[$p]=$(code -L --max-redirs 5 "$B$p"); done
echo "vorher HTTP: $(for p in "${PAGES[@]}" "${APIS[@]}"; do printf '%s=%s ' "$p" "${PRE[$p]}"; done)"
for u in prepper-dashboard; do a=$(systemctl is-active "$u" 2>/dev/null || true); [[ "$a" == active ]] || { [[ "$DRY" == 1 ]] && echo "HINWEIS Dienst $u ist nicht aktiv ($a)" || stop "Dienst $u ist nicht aktiv ($a)"; }; done
SVCS="prepper-dashboard prepper-sdr mesh-bridge mesh-bridge-bayern"
declare -A ACT0 AET0
for u in $SVCS; do ACT0[$u]=$(systemctl is-active "$u" 2>/dev/null || true); AET0[$u]=$(systemctl show -p ActiveEnterTimestamp --value "$u" 2>/dev/null || true); done
echo "Dienste vorher: $(for u in $SVCS; do printf '%s=%s ' "$u" "${ACT0[$u]}"; done)"
OURS=" dashboard.py ups_manager.py prepper_docs.py lage_pages.py "
others() { local f b; for f in "$DASH_DIR"/*.py; do b=$(basename "$f"); [[ "$OURS" == *" $b "* ]] || echo "$b $(s16 "$f")"; done; }
others > "$W/others0.txt"
ready_usv() {
  local limit="${C61_READY_S:-180}" pause t0 now elapsed hc line pyrc cf
  [[ "$limit" =~ ^[0-9]+$ ]] || limit=180
  t0=$(date +%s)
  mkdir -p "$W/html"
  : > "$W/usv-wait.log"
  while true; do
    now=$(date +%s); elapsed=$((now - t0))
    if (( elapsed >= limit )); then
      echo "FAIL Zeit ${limit}s: /lokale-energie noch Startbildschirm oder ohne USV-Kacheln" | tee -a "$W/usv-wait.log"
      return 1
    fi
    if ! systemctl is-active --quiet prepper-dashboard; then
      echo "WAIT ${elapsed}s Dienst nicht aktiv" | tee -a "$W/usv-wait.log"
    else
      cf="$W/html/lokal-try.html"
      hc=$("${CURL[@]}" -o "$cf" -w "%{http_code}" "$B/lokale-energie" || true)
      [[ -z "$hc" ]] && hc=000
      set +e
      line=$(python3 - "$cf" "$hc" << 'PY'
import sys
path, code = sys.argv[1], sys.argv[2]
try:
    html = open(path, encoding="utf-8", errors="replace").read()
except Exception:
    html = ""
need = ("USV SPITZBODEN", "USV EG", "nicht verbunden", "nicht festgelegt", "192.168.178.3", "20 % Ladung oder 5 min", 'id="usvEg"')
hard = ("Traceback (most recent call last)", "jinja2.exceptions", "UndefinedError", "TemplateSyntaxError", "Internal Server Error")
boot = "Dashboard startet" in html
missing = [s for s in need if s not in html]
hit = [s for s in hard if s in html]
if code == "500" or hit:
    print("FAIL HTTP %s Vorlage oder Laufzeit: %s" % (code, ", ".join(hit) or "HTTP 500"))
    sys.exit(2)
if not missing and not boot and code == "200":
    print("READY HTTP 200 USV SPITZBODEN und USV EG, kein Startbildschirm")
    sys.exit(0)
if "USV SPITZBODEN" in html and not boot:
    print("FAIL echte Seite, Inhalt falsch, fehlt: %s" % ", ".join(missing))
    sys.exit(2)
why = []
if boot:
    why.append("Startbildschirm")
if code != "200":
    why.append("HTTP " + code)
if missing:
    why.append("noch ohne USV-Kacheln")
print("WAIT " + ("; ".join(why) or "unvollstaendig"))
sys.exit(1)
PY
)
      pyrc=$?
      set -e
      echo "$line" | tee -a "$W/usv-wait.log"
      if [[ "$pyrc" -eq 0 ]]; then cp -f "$cf" "$W/html/lokal1.html"; echo "OK /lokale-energie bereit nach ${elapsed}s"; return 0; fi
      if [[ "$pyrc" -eq 2 ]]; then return 2; fi
    fi
    pause="${C61_WAIT_S:-2}"; sleep "$pause"
  done
}
if [[ "$STATE" == neu ]]; then
  ready_usv && rc=0 || rc=$?
  if [[ "$rc" -eq 0 ]]; then
    FINISHED=1
    echo "OK $MK laeuft schon (Variante $VARIANT) - nichts geaendert, kein Neustart"
    echo "COMMIT $COMMIT_ARG usvnamen=1 fertig (schon installiert, nichts geaendert)"
    exit 0
  fi
  cat "$W/usv-wait.log"
  stop "$NM ist in den Dateien installiert, aber /lokale-energie zeigt die USV-Kacheln nicht."
fi
rswin() { local m=$(( $1 / 60 % 60 )); [[ $m -ge 55 || $m -lt 5 ]]; }
rssec() { local hm
  if [[ -n "${C61_FAKE_HM:-}" && "$SIM" == 1 ]]; then hm="$C61_FAKE_HM"; echo $(( 10#${hm%%:*} * 3600 + 10#${hm##*:} * 60 + $1 )); return; fi
  echo $(( 10#$(TZ=Europe/Berlin date +%H) * 3600 + 10#$(TZ=Europe/Berlin date +%M) * 60 + 10#$(TZ=Europe/Berlin date +%S) + $1 )); }
rshm() { printf '%02d:%02d' $(( $1 / 3600 % 24 )) $(( $1 / 60 % 60 )); }
rscheck() { local s0 s1; s0=$(rssec 0); s1=$(rssec 300)
  if rswin "$s0" || rswin "$s1"; then
    if [[ "$DRY" == 1 ]]; then echo "HINWEIS Neustart-Sperre: jetzt ($1, $(rshm "$s0") Uhr Berlin) waere ein echter Lauf gesperrt (HH:50 bis HH:04 inklusive) - frei ab HH:05"
    else stop "Neustart-Sperre: es ist $(rshm "$s0") Uhr (Berlin) - Sperre HH:50 bis HH:04 inklusive - prepper-dashboard wird jetzt nicht neu gestartet; bitte ab HH:05 erneut starten"; fi
  else echo "OK Neustart-Sperre: $(rshm "$s0") Uhr (Berlin) liegt ausserhalb HH:50 bis HH:04, auch in 5 min ($1)"; fi; }
rscheck "Vorpruefung"
if [[ "$DRY" == 1 ]]; then
  FINISHED=1
  echo "TROCKENLAUF fertig - nichts installiert, kein Neustart, nichts gesendet. Variante $VARIANT."
  echo "COMMIT $COMMIT_ARG usvnamen=dry fertig"
  exit 0
fi
sudo -v || stop "sudo -v fehlgeschlagen (Passwort noetig?)"
waitd() { local i; for i in $(seq 1 80); do sleep "${C61_WAIT_S:-3}"; systemctl is-active --quiet prepper-dashboard && [[ "$(code "$B/")" == 200 ]] && return 0; done; return 1; }
docls() { { ls -1 "$DOCS" 2>/dev/null || true; } | sha256sum | cut -c1-16; }
DOCS_LS0=$(docls)
rb() {
  set +e +o pipefail
  trap - ERR
  RB_DONE=1
  echo "ROLLBACK: $1"
  local x f bn dok=1
  for x in "${INST[@]}"; do [[ -f "$x.bak-$NM-$TS" ]] && cp -a "$x.bak-$NM-$TS" "$x.rb" && mv -f "$x.rb" "$x"; done
  for x in "${INST[@]}"; do [[ -f "$x.bak-$NM-$TS" ]] && { cmp -s "$x" "$x.bak-$NM-$TS" && echo "  $(basename "$x") = Sicherung ($(s16 "$x"))" || echo "  WARNUNG $(basename "$x") ungleich Sicherung"; }; done
  if [[ "$GEN_RAN" == 1 && -d "$W/docs0" ]]; then
    for f in "$DOCS"/*; do [[ -e "$f" ]] || continue; bn=$(basename "$f"); [[ -e "$W/docs0/$bn" ]] || rm -f -- "$f" || dok=0; done
    for f in "$W/docs0"/*; do [[ -e "$f" ]] || continue; bn=$(basename "$f"); [[ -e "$DOCS/$bn" ]] && cmp -s "$f" "$DOCS/$bn" || cp -p "$f" "$DOCS/$bn" || dok=0; done
    [[ "$dok" == 1 && "$(docls)" == "$DOCS_LS0" ]] && echo "  docs/ wie vorher" || echo "  WARNUNG docs/ nicht sicher wie vorher"
  fi
  if [[ "$RESTARTED" == 1 ]]; then sudo systemctl restart prepper-dashboard.service 9>&-; waitd; fi
  echo "alter Stand wieder aktiv: prepper-dashboard=$(systemctl is-active prepper-dashboard 2>/dev/null), HTTP / = $(code "$B/")"
  echo "  upsmon, killpower, Firewall und Mesh wurden nicht veraendert; nichts gesendet"
}
rbx() { rb "$1"; exit 1; }
rscheck "unmittelbar vor dem Ersetzen"
PHASE=installiert
T0D=$(date +%s)
for f in "${SINGLE[@]}" lage_pages.py; do
  x="$DASH_DIR/$f"
  cp -a "$x" "$x.bak-$NM-$TS"
  cmp -s "$x" "$x.bak-$NM-$TS" || rbx "Sicherung $f ungleich Original"
  { ls -1t "$x.bak-$NM-"* 2>/dev/null || true; } | tail -n +$((KEEP_LAST + 1)) | while read -r o; do rm -f -- "$o"; done
done
echo "OK Sicherungen *.bak-$NM-$TS (behalten: letzte $KEEP_LAST)"
for f in "${SINGLE[@]}"; do
  x="$DASH_DIR/$f"; INST+=("$x")
  cp "$W/neu/$f" "$x.new" && chmod --reference="$x.bak-$NM-$TS" "$x.new" && mv -f "$x.new" "$x" || { rm -f "$x.new"; rbx "$f installieren"; }
  [[ "$(sfull "$x")" == "${NEU[$f]}" ]] || rbx "$f nach dem Kopieren falsch"
done
x="$DASH_DIR/lage_pages.py"; INST+=("$x")
src="$W/neu/lage_full.py"; [[ "$VARIANT" == trim ]] && src="$W/neu/lage_trim.py"
cp "$src" "$x.new" && chmod --reference="$x.bak-$NM-$TS" "$x.new" && mv -f "$x.new" "$x" || { rm -f "$x.new"; rbx "lage_pages.py installieren"; }
want="$LAGE_NEU_FULL"; [[ "$VARIANT" == trim ]] && want="$LAGE_NEU_TRIM"
[[ "$(sfull "$x")" == "$want" ]] || rbx "lage_pages.py nach dem Kopieren falsch ($(s16 "$x"), Variante $VARIANT)"
echo "OK vier Dateien atomar ersetzt (lage_pages.py Variante $VARIANT)"
for py in "$SPY" "$VPY"; do
  for f in "${SINGLE[@]}" lage_pages.py; do
    "$py" -W error -c 'import sys; compile(open(sys.argv[1], encoding="utf-8").read(), sys.argv[1], "exec")' "$DASH_DIR/$f" 2>"$W/pyc.log" || { cat "$W/pyc.log"; rbx "py_compile $f mit $py"; }
  done
done
RESTARTED=1
echo "Neustart prepper-dashboard (nur dieser Dienst) - warte auf die echte Seite /lokale-energie (max ${C61_READY_S:-180} s) ..."
sudo systemctl restart prepper-dashboard.service 9>&-
ready_usv && rc=0 || rc=$?
if [[ "$rc" -ne 0 ]]; then cat "$W/usv-wait.log"; rbx "/lokale-energie nach dem Neustart nicht die echte USV-Seite"; fi
for p in "${PAGES[@]}" "${APIS[@]}"; do
  c=$(code_r -L --max-redirs 5 "$B$p")
  [[ "$c" == "${PRE[$p]}" ]] || rbx "$p antwortet $c (vorher ${PRE[$p]})"
done
echo "OK Smoke-Test: ${#PAGES[@]} Seiten und ${#APIS[@]} APIs antworten wie vorher"
others > "$W/others1.txt"; cmp -s "$W/others0.txt" "$W/others1.txt" || rbx "andere Programmdateien haben sich veraendert"
for u in $SVCS; do
  [[ "$u" == prepper-dashboard ]] && continue
  a=$(systemctl is-active "$u" 2>/dev/null || true); t=$(systemctl show -p ActiveEnterTimestamp --value "$u" 2>/dev/null || true)
  [[ "$a" == "${ACT0[$u]}" && "$t" == "${AET0[$u]}" ]] || rbx "Dienst $u hat sich veraendert"
done
echo "OK nur prepper-dashboard neu gestartet; prepper-sdr und Mesh unveraendert; nichts gesendet"
PHASE=fertig
FINISHED=1
echo "COMMIT $COMMIT_ARG usvnamen=1 fertig dashboard=${NEU[dashboard.py]:0:16} ups_manager=${NEU[ups_manager.py]:0:16} lage_pages=${want:0:16} prepper_docs=${NEU[prepper_docs.py]:0:16} variante=$VARIANT"
